files.content:
.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #000000;
  --vt-accent-ink: #247cff;
  --vt-accent-on-deep: #247cff;
  --vt-line: #eaeaea;

  padding-top: 94px;
  min-height: 100vh;
  background: var(--vt-surface);
  font-family: 'Open Sans', sans-serif;
  color: var(--vt-ink-soft);
  box-sizing: border-box;
}

.root *,
.root *::before,
.root *::after {
  box-sizing: inherit;
}

.root a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  transition: color 0.3s;
}

.root a:hover {
  color: var(--vt-accent);
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

.root h1,
.root h2,
.root h3,
.root h4,
.root h5,
.root h6 {
  color: var(--vt-ink);
  font-weight: 600;
  line-height: 1.2;
}

.root h1 {
  font-size: 48px;
  font-weight: 700;
}

.root h2 {
  font-size: 36px;
  font-weight: 700;
}

.root h3 {
  font-size: 32px;
}

.root h4 {
  font-size: 28px;
}

.root h5 {
  font-size: 24px;
}

.root h6 {
  font-size: 22px;
}

.root p {
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
  line-height: 1.6;
}

.sectionPadding {
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.section {
  /* optional */
}

.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.nav {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.15);
  z-index: 1000;
  padding-top: 20px;
  padding-bottom: 20px;
}

.navIn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.logo {
  text-decoration: none;
  color: var(--vt-accent);
  font-size: 24px;
  font-weight: 700;
  display: flex;
  align-items: center;
}

.logo:hover {
  color: var(--vt-accent);
}

.brand {
  display: inline-block;
}

.navLinks {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}

.navLinks a {
  color: var(--vt-ink-soft);
  font-weight: 600;
  font-size: 16px;
  padding: 15px 0;
  transition: color 0.3s;
}

.navLinks a:hover,
.navLinks a:focus {
  color: var(--vt-ink);
}

.hero {
  padding-top: 0;
  position: relative;
}

.heroTrack {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  height: 580px;
}

.heroSlide {
  flex: 0 0 100%;
  scroll-snap-align: start;
  height: 100%;
  object-fit: cover;
  width: 100%;
}

.heroText {
  background: var(--vt-surface);
  position: absolute;
  z-index: 2;
  bottom: 0;
  right: 0;
  padding: 1.5rem 2.5rem;
  width: 50%;
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.15);
}

.heroTitle {
  margin-top: auto;
  margin-bottom: 0.5rem;
  font-size: 48px;
}

.animatedInfo {
  display: inline-block;
  vertical-align: top;
  min-width: 250px;
  position: relative;
}

.animatedItem {
  color: var(--vt-accent);
  display: block;
  opacity: 0;
  overflow: hidden;
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  animation: bottomToTop 6s linear infinite 0s;
}

@keyframes bottomToTop {
  0% { opacity: 0; }
  5% { opacity: 0; transform: translateY(5px); }
  10% { opacity: 1; transform: translateY(0); }
  25% { opacity: 1; transform: translateY(0); }
  30% { opacity: 0; transform: translateY(5px); }
  80% { opacity: 0; }
  100% { opacity: 0; }
}

.heroLinks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  margin-top: 1rem;
}

.customLink {
  display: inline-block;
  text-decoration: none;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  position: relative;
  padding: 0 30px;
  box-sizing: border-box;
  margin-right: 1rem;
  user-select: none;
  overflow: hidden;
  text-transform: uppercase;
  transition: all 0.3s;
}

.customLink::before {
  content: attr(data-hover);
  background-color: var(--vt-line);
  color: var(--vt-accent);
  position: absolute;
  top: 100%;
  bottom: 0;
  left: 0;
  transition: top 300ms cubic-bezier(0.19, 1, 0.56, 1);
  right: 0;
  text-align: center;
}

.customLink:hover::before {
  top: 0;
}

.contactPhone {
  font-weight: 600;
  color: var(--vt-ink);
  margin-bottom: 0;
}

.aboutRow {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
}

.aboutText {
  flex: 1 1 100%;
  max-width: 800px;
}

.aboutTitle {
  margin-bottom: 1rem;
}

.gallery {
  overflow: hidden;
}

.galleryRow {
  display: flex;
  flex-wrap: wrap;
  margin: 0 -15px;
}

.galleryItem {
  flex: 1 1 50%;
  padding: 0 15px;
}

.galleryImage {
  width: 100%;
  height: auto;
  display: block;
}

.timelineTitle {
  text-align: center;
  margin-bottom: 3rem;
}

.timeline {
  position: relative;
  padding: 0 0 4rem;
}

.timeline::before {
  content: "";
  display: block;
  position: absolute;
  top: 37px;
  left: 50%;
  width: 0;
  border-left: 1px solid var(--vt-line);
  height: calc(100% - 74px);
  transform: translateX(-50%);
  z-index: 1;
}

.timelineNodes {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 60px 1fr;
  align-items: start;
  margin: 2.5rem 0;
}

.timelineNodes:nth-child(even) {
  grid-template-columns: 1fr 60px 1fr;
}

.timelineOdd .timelineContent {
  order: 1;
  padding-right: 2rem;
}

.timelineOdd .timelineIcons {
  order: 2;
}

.timelineOdd .timelineDate {
  order: 3;
  padding-left: 2rem;
  text-align: left;
}

.timelineEven .timelineContent {
  order: 3;
  padding-left: 2rem;
}

.timelineEven .timelineIcons {
  order: 2;
}

.timelineEven .timelineDate {
  order: 1;
  padding-right: 2rem;
  text-align: right;
}

.timelineContent {
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.15);
  border-radius: 0 0 0.25rem 0.25rem;
  padding: 0;
  position: relative;
  max-width: 100%;
}

.timelineHeading {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  border-radius: 0.25rem 0.25rem 0 0;
  position: relative;
}

.timelineOdd .timelineHeading::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translateY(-50%);
  width: 0;
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineEven .timelineHeading::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translateY(-50%);
  width: 0;
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineContent p {
  padding: 10px 30px;
  margin: 0;
}

.timelineMeta {
  font-weight: 600;
  color: var(--vt-accent);
}

.timelineIcons {
  position: relative;
  z-index: 10;
  display: flex;
  justify-content: center;
}

.timelineIcons::before {
  content: "";
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0,0,0,0.175);
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  z-index: -1;
}

.timelineIcon {
  font-size: 32px;
  color: var(--vt-accent);
  line-height: 80px;
  text-align: center;
}

.timelineDate {
  color: var(--vt-ink-soft);
  font-size: 16px;
  padding-top: 1.5rem;
}

.contactTitle {
  text-align: center;
  margin-bottom: 3rem;
}

.contactRow {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
}

.contactInfo {
  flex: 1 1 40%;
  min-width: 250px;
}

.contactInfo p {
  margin-bottom: 0.5rem;
}

.findUs {
  flex: 1 1 55%;
  min-width: 250px;
  max-width: 100%;
  overflow: hidden;
}

.footer {
  background: var(--vt-surface-2);
  padding-top: 5rem;
  padding-bottom: 3rem;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
}

.footerHours {
  flex: 1 1 30%;
  min-width: 200px;
}

.footerClinic {
  flex: 1 1 20%;
  min-width: 150px;
}

.footerSocials {
  flex: 1 1 20%;
  min-width: 150px;
}

.footerCopyright {
  flex: 1 1 100%;
  margin-top: 2rem;
  text-align: center;
}

.footerCopyright p {
  font-size: 16px;
  color: var(--vt-ink-soft);
}

@media screen and (min-width: 1600px) {
  .heroTrack {
    height: 740px;
  }
}

@media screen and (max-width: 991px) {
  .root {
    padding-top: 74px;
  }

  .root h1 {
    font-size: 38px;
  }

  .root h2 {
    font-size: 32px;
  }

  .root h3 {
    font-size: 26px;
  }

  .root h4 {
    font-size: 24px;
  }

  .root h5 {
    font-size: 20px;
  }

  .root h6 {
    font-size: 18px;
  }

  .sectionPadding {
    padding-top: 5rem;
    padding-bottom: 5rem;
  }

  .nav {
    padding-top: 10px;
    padding-bottom: 10px;
  }

  .navLinks a {
    padding-top: 5px;
    padding-bottom: 10px;
  }

  .heroTrack {
    height: auto;
  }

  .heroText {
    position: relative;
    bottom: auto;
    left: 0;
    width: auto;
    margin: -100px 15px 0;
    padding: 2rem;
    box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.15);
  }

  .heroTrack {
    display: block;
    overflow-x: visible;
  }

  .heroSlide {
    width: 100%;
    height: auto;
    display: block;
  }

  .timeline::before {
    left: 33px;
    top: 60px;
    height: calc(100% - 120px);
    transform: none;
  }

  .timelineNodes {
    grid-template-columns: 60px 1fr;
    gap: 0;
  }

  .timelineOdd .timelineContent,
  .timelineEven .timelineContent {
    order: 2;
    padding: 0 0 0 2rem;
  }

  .timelineOdd .timelineIcons,
  .timelineEven .timelineIcons {
    order: 1;
    position: absolute;
    left: 0;
    top: 0;
  }

  .timelineOdd .timelineDate,
  .timelineEven .timelineDate {
    order: 3;
    grid-column: 2;
    text-align: left;
    padding: 1rem 0 0 2rem;
  }

  .timelineOdd .timelineHeading::after,
  .timelineEven .timelineHeading::after {
    left: auto;
    right: 100%;
    border-left: 0;
    border-right: 10px solid var(--vt-surface-deep);
    border-top: 10px solid transparent;
    border-bottom: 10px solid transparent;
  }

  .timelineIcons::before {
    width: 75px;
    height: 75px;
    left: 0;
    transform: none;
  }

  .timelineIcon {
    line-height: 75px;
  }

  .footerRow {
    justify-content: space-between;
  }
}

@media screen and (max-width: 767px) {
  .heroText {
    padding: 1.5rem;
  }

  .animatedInfo {
    min-width: 125px;
  }

  .timelineNodes {
    grid-template-columns: 60px 1fr;
  }

  .timelineIcons {
    position: absolute;
    left: 0;
    top: 60px;
  }

  .timelineIcons::before {
    left: 0;
    transform: none;
  }
}

@media screen and (max-width: 575px) {
  .timeline::before {
    left: 57px;
  }

  .timelineIcons {
    left: -10px;
  }

  .timelineIcons::before {
    width: 70px;
    height: 70px;
  }

  .timelineIcon {
    line-height: 70px;
  }
}

@media screen and (max-width: 480px) {
  .heroText {
    padding: 1rem;
  }

  .heroLinks .customLink {
    font-size: 12px;
    line-height: 30px;
    margin-right: 12px;
    padding: 0 25px;
  }

  .contactPhone {
    font-size: 12px;
  }
}

@media screen and (max-width: 360px) {
  .timeline::before {
    left: 42px;
  }
}
